import { expect } from "chai";
import { MetricsRegistry, isExportableUpdate, toMetricValue } from "./exporter";

describe("exporter => toMetricValue", () => {
    it("passes finite numbers through", () => {
        expect(toMetricValue(21.5)).to.equal(21.5);
        expect(toMetricValue(0)).to.equal(0);
    });

    it("maps booleans to 0/1", () => {
        expect(toMetricValue(true)).to.equal(1);
        expect(toMetricValue(false)).to.equal(0);
    });

    it("parses numeric strings", () => {
        expect(toMetricValue("42.5")).to.equal(42.5);
    });

    it("rejects everything else", () => {
        expect(toMetricValue("on")).to.equal(undefined);
        expect(toMetricValue(null)).to.equal(undefined);
        expect(toMetricValue(Number.NaN)).to.equal(undefined);
        expect(toMetricValue(Number.POSITIVE_INFINITY)).to.equal(undefined);
    });
});

describe("exporter => MetricsRegistry", () => {
    it("renders default metrics with id and name labels", () => {
        const registry = new MetricsRegistry();
        registry.set("zigbee.0.sensor.temperature", { name: "Wohnzimmer Temp", value: 21.5 });
        const text = registry.render();
        expect(text).to.include("# TYPE iobroker_state gauge");
        expect(text).to.include('iobroker_state{id="zigbee.0.sensor.temperature",name="Wohnzimmer Temp"} 21.5');
    });

    it("supports a custom metric name per state", () => {
        const registry = new MetricsRegistry();
        registry.set("hm-rpc.0.power", { name: "Steckdose", value: 12, metricName: "iobroker_power_watts" });
        const text = registry.render();
        expect(text).to.include("# TYPE iobroker_power_watts gauge");
        expect(text).to.include('iobroker_power_watts{id="hm-rpc.0.power",name="Steckdose"} 12');
    });

    it("falls back to the default metric for invalid custom names", () => {
        const registry = new MetricsRegistry();
        registry.set("a.0.x", { name: "x", value: 1, metricName: 'bad name{)"' });
        const text = registry.render();
        expect(text).to.include('iobroker_state{id="a.0.x"');
        expect(text).to.not.include("bad name");
    });

    it("escapes label values", () => {
        const registry = new MetricsRegistry();
        registry.set("a.0.b", { name: 'has "quote" and \\slash', value: 1 });
        expect(registry.render()).to.include('name="has \\"quote\\" and \\\\slash"');
    });

    it("omits states without a numeric value and removed states", () => {
        const registry = new MetricsRegistry();
        registry.set("a.0.b", { name: "b", value: undefined });
        registry.set("a.0.c", { name: "c", value: 2 });
        registry.remove("a.0.c");
        const text = registry.render();
        expect(text).to.not.include("a.0.b");
        expect(text).to.not.include("a.0.c");
    });

    it("groups multiple states under one TYPE header per metric", () => {
        const registry = new MetricsRegistry();
        registry.set("a.0.one", { name: "one", value: 1 });
        registry.set("a.0.two", { name: "two", value: 2 });
        const text = registry.render();
        expect(text.match(/# TYPE iobroker_state gauge/g)).to.have.lengthOf(1);
        expect(text.indexOf('id="a.0.one"')).to.be.greaterThan(-1);
        expect(text.indexOf('id="a.0.two"')).to.be.greaterThan(-1);
    });

    it("updates only the value of an already tracked state", () => {
        const registry = new MetricsRegistry();
        registry.set("a.0.b", { name: "b", value: 1, metricName: "iobroker_power_watts" });
        registry.updateValue("a.0.b", 2);
        registry.updateValue("a.0.unknown", 5);
        const text = registry.render();
        expect(text).to.include('iobroker_power_watts{id="a.0.b",name="b"} 2');
        expect(text).to.not.include("unknown");
    });

    it("reports the number of exported states", () => {
        const registry = new MetricsRegistry();
        expect(registry.size).to.equal(0);
        registry.set("a.0.b", { name: "b", value: 1 });
        expect(registry.size).to.equal(1);
    });
});

describe("exporter => isExportableUpdate", () => {
    it("accepts acknowledged values", () => {
        expect(isExportableUpdate({ ack: true })).to.equal(true);
    });

    it("ignores unacknowledged commands", () => {
        expect(isExportableUpdate({ ack: false })).to.equal(false);
    });

    it("accepts a deleted state so its value gets removed", () => {
        expect(isExportableUpdate(null)).to.equal(true);
        expect(isExportableUpdate(undefined)).to.equal(true);
    });
});

/**
 * Pull exporter: exposes selected ioBroker states in the Prometheus text
 * exposition format so a Prometheus server can scrape them.
 *
 * https://prometheus.io/docs/instrumenting/exposition_formats/
 */

import { escapeLabelValue, isValidMetricName } from "./query-builder";

/** Default metric name for exported states without a custom name */
export const DEFAULT_METRIC_NAME = "iobroker_state";

/** One exported state as tracked by the registry */
export interface ExportedState {
    /** Human readable name of the state (label "name") */
    name: string;
    /** Current numeric value; undefined when the value is not exportable */
    value: number | undefined;
    /** Optional custom metric name from the per-datapoint settings */
    metricName?: string;
}

/**
 * Converts an ioBroker state value into a Prometheus sample value
 *
 * @param value - The raw state value
 * @returns The finite number to export, or undefined if not exportable
 */
export function toMetricValue(value: unknown): number | undefined {
    if (typeof value === "boolean") {
        return value ? 1 : 0;
    }
    if (typeof value === "number" || (typeof value === "string" && value.trim() !== "")) {
        const parsed = Number(value);
        return Number.isFinite(parsed) ? parsed : undefined;
    }
    return undefined;
}

/**
 * Decides whether a state update may change the exported value.
 * Unacknowledged commands (ack=false) are not exported; a deleted state
 * (null/undefined) is, so its stale value gets removed.
 *
 * @param state - The state as delivered by ioBroker
 */
export function isExportableUpdate(state: Pick<ioBroker.State, "ack"> | null | undefined): boolean {
    return !state || state.ack;
}

/** Holds the current values of all exported states and renders them */
export class MetricsRegistry {
    private readonly states = new Map<string, ExportedState>();

    /** Number of tracked states */
    public get size(): number {
        return this.states.size;
    }

    /**
     * Adds or updates one exported state
     *
     * @param id - The ioBroker state id
     * @param entry - Name, current value and optional custom metric name
     */
    public set(id: string, entry: ExportedState): void {
        this.states.set(id, entry);
    }

    /**
     * Updates the value of an already tracked state; unknown ids are ignored
     *
     * @param id - The ioBroker state id
     * @param value - The new sample value (undefined removes the sample)
     */
    public updateValue(id: string, value: number | undefined): void {
        const entry = this.states.get(id);
        if (entry) {
            this.states.set(id, { ...entry, value });
        }
    }

    /**
     * Stops exporting one state
     *
     * @param id - The ioBroker state id
     */
    public remove(id: string): void {
        this.states.delete(id);
    }

    /** Removes all tracked states */
    public clear(): void {
        this.states.clear();
    }

    /** Renders all current values in the Prometheus text exposition format */
    public render(): string {
        // group samples by metric name so each metric gets exactly one TYPE header
        const byMetric = new Map<string, string[]>();
        for (const [id, entry] of this.states) {
            if (entry.value === undefined) {
                continue;
            }
            const metric =
                entry.metricName && isValidMetricName(entry.metricName) ? entry.metricName : DEFAULT_METRIC_NAME;
            const labels = `id="${escapeLabelValue(id)}",name="${escapeLabelValue(entry.name)}"`;
            let lines = byMetric.get(metric);
            if (!lines) {
                lines = [];
                byMetric.set(metric, lines);
            }
            lines.push(`${metric}{${labels}} ${entry.value}`);
        }

        const output: string[] = [];
        for (const [metric, lines] of [...byMetric.entries()].sort(([a], [b]) => a.localeCompare(b))) {
            output.push(`# HELP ${metric} ioBroker state values exported by iobroker.prometheus`);
            output.push(`# TYPE ${metric} gauge`);
            output.push(...lines.sort());
        }
        return output.length > 0 ? `${output.join("\n")}\n` : "";
    }
}

/**
 * Builds PromQL queries from structured configuration values.
 *
 * The Admin UI never lets the user type raw PromQL. Every part of the query
 * (metric, filters, aggregation, groupBy) is validated here so that user
 * configuration can never inject arbitrary PromQL.
 */

export const AGGREGATIONS = ["none", "avg", "sum", "min", "max", "count"] as const;
export type Aggregation = (typeof AGGREGATIONS)[number];

/** One exact-match label filter of a selector */
export interface QueryFilter {
    /** Label name to match */
    label: string;
    /** Exact label value to match */
    value: string;
}

/** Structured description of a PromQL instant query */
export interface QuerySpec {
    /** Metric name */
    metric: string;
    /** Exact-match label filters */
    filters: QueryFilter[];
    /** Aggregation applied over all matching series */
    aggregation: Aggregation;
    /** Labels for the "by (...)" clause; only used with an aggregation */
    groupBy: string[];
}

// https://prometheus.io/docs/concepts/data_model/#metric-names-and-labels
const METRIC_NAME_REGEX = /^[a-zA-Z_:][a-zA-Z0-9_:]*$/;
const LABEL_NAME_REGEX = /^[a-zA-Z_][a-zA-Z0-9_]*$/;

/**
 * Returns true if the given string is a valid Prometheus metric name
 *
 * @param metric - The metric name to validate
 */
export function isValidMetricName(metric: string): boolean {
    return METRIC_NAME_REGEX.test(metric);
}

/**
 * Returns true if the given string is a valid Prometheus label name
 *
 * @param label - The label name to validate
 */
export function isValidLabelName(label: string): boolean {
    return LABEL_NAME_REGEX.test(label);
}

/**
 * Escapes a label value for use inside double quotes in a PromQL selector
 *
 * @param value - The raw label value
 */
export function escapeLabelValue(value: string): string {
    return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");
}

/**
 * Builds a PromQL query string from a validated query specification.
 *
 * @param spec - Structured query parts collected by the Admin UI
 * @returns The PromQL query string
 * @throws {Error} If any part of the specification is invalid
 */
export function buildQuery(spec: QuerySpec): string {
    if (!isValidMetricName(spec.metric)) {
        throw new Error(`Invalid metric name: "${spec.metric}"`);
    }
    if (!AGGREGATIONS.includes(spec.aggregation)) {
        throw new Error(`Invalid aggregation: "${String(spec.aggregation)}"`);
    }

    const matchers = spec.filters.map(filter => {
        if (!isValidLabelName(filter.label)) {
            throw new Error(`Invalid filter label name: "${filter.label}"`);
        }
        return `${filter.label}="${escapeLabelValue(filter.value)}"`;
    });

    const selector = matchers.length > 0 ? `${spec.metric}{${matchers.join(",")}}` : spec.metric;

    if (spec.aggregation === "none") {
        return selector;
    }

    if (spec.groupBy.length > 0) {
        for (const label of spec.groupBy) {
            if (!isValidLabelName(label)) {
                throw new Error(`Invalid groupBy label name: "${label}"`);
            }
        }
        return `${spec.aggregation} by (${spec.groupBy.join(",")}) (${selector})`;
    }

    return `${spec.aggregation}(${selector})`;
}

import { expect } from "chai";
import https from "node:https";
import sinon from "sinon";
import { PrometheusClient } from "./prometheus-client";

function clientWithResponse(data: unknown): { client: PrometheusClient; get: sinon.SinonStub } {
    const get = sinon.stub().resolves({ data });
    const client = new PrometheusClient({ baseUrl: "http://prom:9090", timeoutMs: 5000 }, get);
    return { client, get };
}

describe("prometheus-client => instantQuery", () => {
    it("parses a vector response into samples", async () => {
        const { client, get } = clientWithResponse({
            status: "success",
            data: {
                resultType: "vector",
                result: [
                    { metric: { instance: "a" }, value: [1726000000, "1.5"] },
                    { metric: { instance: "b" }, value: [1726000000, "2"] },
                ],
            },
        });

        const samples = await client.instantQuery('up{job="node"}');
        expect(samples).to.deep.equal([
            { labels: { instance: "a" }, value: 1.5 },
            { labels: { instance: "b" }, value: 2 },
        ]);
        const [url, options] = get.firstCall.args;
        expect(url).to.equal("http://prom:9090/api/v1/query");
        expect(options.params.query).to.equal('up{job="node"}');
    });

    it("parses a scalar response into a single unlabeled sample", async () => {
        const { client } = clientWithResponse({
            status: "success",
            data: { resultType: "scalar", result: [1726000000, "42"] },
        });

        const samples = await client.instantQuery("scalar(up)");
        expect(samples).to.deep.equal([{ labels: {}, value: 42 }]);
    });

    it("drops non-finite sample values (NaN, Inf)", async () => {
        const { client } = clientWithResponse({
            status: "success",
            data: {
                resultType: "vector",
                result: [
                    { metric: { instance: "a" }, value: [1726000000, "NaN"] },
                    { metric: { instance: "b" }, value: [1726000000, "+Inf"] },
                    { metric: { instance: "c" }, value: [1726000000, "3"] },
                ],
            },
        });
        const samples = await client.instantQuery("up");
        expect(samples).to.deep.equal([{ labels: { instance: "c" }, value: 3 }]);
    });

    it("returns an empty list for an empty vector", async () => {
        const { client } = clientWithResponse({
            status: "success",
            data: { resultType: "vector", result: [] },
        });
        expect(await client.instantQuery("up")).to.deep.equal([]);
    });

    it("throws a descriptive error on a Prometheus error envelope", async () => {
        const { client } = clientWithResponse({ status: "error", errorType: "bad_data", error: "parse error" });
        await expect(client.instantQuery("up")).to.be.rejectedWith(/parse error/);
    });

    it("throws on an unexpected response shape", async () => {
        const { client } = clientWithResponse("not-json-envelope");
        await expect(client.instantQuery("up")).to.be.rejectedWith(/unexpected/i);
    });
});

describe("prometheus-client => label endpoints", () => {
    it("fetches metric names from the __name__ endpoint", async () => {
        const { client, get } = clientWithResponse({ status: "success", data: ["up", "node_load1"] });
        const names = await client.metricNames();
        expect(names).to.deep.equal(["up", "node_load1"]);
        expect(get.firstCall.args[0]).to.equal("http://prom:9090/api/v1/label/__name__/values");
    });

    it("fetches label names, optionally narrowed by metric", async () => {
        const { client, get } = clientWithResponse({ status: "success", data: ["instance", "job"] });
        const labels = await client.labelNames("node_load1");
        expect(labels).to.deep.equal(["instance", "job"]);
        const [url, options] = get.firstCall.args;
        expect(url).to.equal("http://prom:9090/api/v1/labels");
        expect(options.params["match[]"]).to.equal("node_load1");
    });

    it("fetches values for a label", async () => {
        const { client, get } = clientWithResponse({ status: "success", data: ["idle", "user"] });
        const values = await client.labelValues("mode");
        expect(values).to.deep.equal(["idle", "user"]);
        expect(get.firstCall.args[0]).to.equal("http://prom:9090/api/v1/label/mode/values");
    });

    it("rejects invalid label names instead of building a bad URL", async () => {
        const { client } = clientWithResponse({ status: "success", data: [] });
        await expect(client.labelValues("../../admin")).to.be.rejectedWith(/label/i);
    });

    it("filters non-string entries from list responses", async () => {
        const { client } = clientWithResponse({ status: "success", data: ["ok", 5, null, "also-ok"] });
        expect(await client.metricNames()).to.deep.equal(["ok", "also-ok"]);
    });
});

describe("prometheus-client => auth", () => {
    it("passes basic auth credentials when configured", async () => {
        const get = sinon.stub().resolves({ data: { status: "success", data: [] } });
        const client = new PrometheusClient(
            { baseUrl: "http://prom:9090", timeoutMs: 5000, username: "user", password: "secret" },
            get,
        );
        await client.metricNames();
        expect(get.firstCall.args[1].auth).to.deep.equal({ username: "user", password: "secret" });
    });

    it("omits auth when no username is configured", async () => {
        const { client, get } = clientWithResponse({ status: "success", data: [] });
        await client.metricNames();
        expect(get.firstCall.args[1].auth).to.equal(undefined);
    });
});

describe("prometheus-client => TLS", () => {
    it("passes the configured HTTPS agent to every request", async () => {
        const get = sinon.stub().resolves({ data: { status: "success", data: [] } });
        const httpsAgent = new https.Agent();
        const client = new PrometheusClient({ baseUrl: "https://prom:9090", timeoutMs: 5000, httpsAgent }, get);

        await client.labelNames();
        expect(get.firstCall.args[1].httpsAgent).to.equal(httpsAgent);
    });

    it("sends no agent when none is configured", async () => {
        const { client, get } = clientWithResponse({ status: "success", data: [] });

        await client.labelNames();
        expect(get.firstCall.args[1].httpsAgent).to.equal(undefined);
    });
});

/**
 * Thin client for the Prometheus HTTP API (v1).
 *
 * Only the read endpoints needed by this adapter are implemented:
 * - /api/v1/query                      (instant queries)
 * - /api/v1/labels                     (label names)
 * - /api/v1/label/<name>/values        (label / metric name values)
 *
 * https://prometheus.io/docs/prometheus/latest/querying/api/
 */

import axios from "axios";
import type https from "node:https";
import { isValidLabelName, isValidMetricName } from "./query-builder";

/** Connection options for one Prometheus server */
export interface PrometheusClientOptions {
    /** Base URL of the Prometheus server without trailing slash */
    baseUrl: string;
    /** HTTP request timeout in milliseconds */
    timeoutMs: number;
    /** Optional basic auth user name */
    username?: string;
    /** Optional basic auth password */
    password?: string;
    /** Optional HTTPS agent carrying custom TLS settings (custom CA, insecure mode) */
    httpsAgent?: https.Agent;
}

/** One sample of an instant query result */
export interface PromSample {
    /** Labels identifying the series this sample belongs to */
    labels: Record<string, string>;
    /** The sample value */
    value: number;
}

interface RequestOptions {
    params?: Record<string, string>;
    auth?: { username: string; password: string };
    timeout: number;
    httpsAgent?: https.Agent;
}

/** Minimal HTTP GET signature so tests can inject a stub instead of axios */
export type HttpGet = (url: string, options: RequestOptions) => Promise<{ data: unknown }>;

interface PromEnvelope {
    status: string;
    data?: unknown;
    error?: string;
    errorType?: string;
}

interface PromQueryData {
    resultType?: string;
    result?: unknown;
}

interface PromVectorEntry {
    metric?: Record<string, string>;
    value: [number, string];
}

function isEnvelope(data: unknown): data is PromEnvelope {
    return typeof data === "object" && data !== null && typeof (data as PromEnvelope).status === "string";
}

function isVectorEntry(entry: unknown): entry is PromVectorEntry {
    return typeof entry === "object" && entry !== null && Array.isArray((entry as PromVectorEntry).value);
}

/** Client for the read endpoints of one Prometheus server */
export class PrometheusClient {
    private readonly options: PrometheusClientOptions;
    private readonly httpGet: HttpGet;

    /**
     * @param options - Connection options for the Prometheus server
     * @param httpGet - Optional HTTP implementation override (used by unit tests)
     */
    public constructor(options: PrometheusClientOptions, httpGet?: HttpGet) {
        this.options = options;
        this.httpGet = httpGet ?? ((url, requestOptions) => axios.get(url, requestOptions));
    }

    /**
     * Runs an instant query and returns all resulting samples
     *
     * @param query - The PromQL query to execute
     */
    public async instantQuery(query: string): Promise<PromSample[]> {
        const data = (await this.request("/api/v1/query", { query })) as PromQueryData | undefined;

        if (data?.resultType === "scalar" && Array.isArray(data.result)) {
            return [{ labels: {}, value: Number(data.result[1]) }].filter(sample => Number.isFinite(sample.value));
        }

        if (data?.resultType === "vector" && Array.isArray(data.result)) {
            return (
                data.result
                    .filter(isVectorEntry)
                    .map(entry => ({
                        labels: entry.metric ?? {},
                        value: Number(entry.value[1]),
                    }))
                    // Prometheus can return NaN/+Inf/-Inf; those are not usable as state values
                    .filter(sample => Number.isFinite(sample.value))
            );
        }

        throw new Error(`Unexpected query result type "${data?.resultType ?? "unknown"}"`);
    }

    /** Returns all known metric names of the Prometheus instance */
    public metricNames(): Promise<string[]> {
        return this.stringList("/api/v1/label/__name__/values");
    }

    /**
     * Returns all label names, optionally narrowed to a metric
     *
     * @param metric - Optional metric name used as match[] selector
     */
    public labelNames(metric?: string): Promise<string[]> {
        return this.stringList("/api/v1/labels", this.matchParams(metric));
    }

    /**
     * Returns all values of one label, optionally narrowed to a metric
     *
     * @param label - The label name whose values are requested
     * @param metric - Optional metric name used as match[] selector
     */
    public labelValues(label: string, metric?: string): Promise<string[]> {
        if (!isValidLabelName(label)) {
            return Promise.reject(new Error(`Invalid label name: "${label}"`));
        }
        return this.stringList(`/api/v1/label/${encodeURIComponent(label)}/values`, this.matchParams(metric));
    }

    private matchParams(metric?: string): Record<string, string> | undefined {
        if (metric && isValidMetricName(metric)) {
            return { "match[]": metric };
        }
        return undefined;
    }

    private async stringList(path: string, params?: Record<string, string>): Promise<string[]> {
        const data = await this.request(path, params);
        if (!Array.isArray(data)) {
            throw new Error(`Unexpected response from ${path}: expected an array`);
        }
        return data.filter((entry): entry is string => typeof entry === "string");
    }

    private async request(path: string, params?: Record<string, string>): Promise<unknown> {
        const response = await this.httpGet(`${this.options.baseUrl}${path}`, {
            params,
            timeout: this.options.timeoutMs,
            httpsAgent: this.options.httpsAgent,
            auth: this.options.username
                ? { username: this.options.username, password: this.options.password ?? "" }
                : undefined,
        });

        if (!isEnvelope(response.data)) {
            throw new Error(`Unexpected response from ${path}: not a Prometheus API envelope`);
        }
        if (response.data.status !== "success") {
            throw new Error(
                `Prometheus API error (${response.data.errorType ?? "unknown"}): ${response.data.error ?? "no details"}`,
            );
        }
        return response.data.data;
    }
}

import { expect } from "chai";
import { buildQuery, escapeLabelValue, isValidLabelName, isValidMetricName } from "./query-builder";

describe("query-builder => isValidMetricName", () => {
    it("accepts valid metric names", () => {
        expect(isValidMetricName("node_cpu_seconds_total")).to.be.true;
        expect(isValidMetricName("up")).to.be.true;
        expect(isValidMetricName(":recording:rule")).to.be.true;
        expect(isValidMetricName("_hidden_metric")).to.be.true;
    });

    it("rejects invalid metric names", () => {
        expect(isValidMetricName("")).to.be.false;
        expect(isValidMetricName("1starts_with_digit")).to.be.false;
        expect(isValidMetricName("has space")).to.be.false;
        expect(isValidMetricName('inject"}or 1')).to.be.false;
        expect(isValidMetricName("umlaut_ä")).to.be.false;
    });
});

describe("query-builder => isValidLabelName", () => {
    it("accepts valid label names", () => {
        expect(isValidLabelName("instance")).to.be.true;
        expect(isValidLabelName("_meta")).to.be.true;
        expect(isValidLabelName("cpu0")).to.be.true;
    });

    it("rejects invalid label names", () => {
        expect(isValidLabelName("")).to.be.false;
        expect(isValidLabelName("0cpu")).to.be.false;
        expect(isValidLabelName("with:colon")).to.be.false;
        expect(isValidLabelName('a"b')).to.be.false;
    });
});

describe("query-builder => escapeLabelValue", () => {
    it("escapes backslashes, quotes and newlines", () => {
        expect(escapeLabelValue("plain")).to.equal("plain");
        expect(escapeLabelValue('has"quote')).to.equal('has\\"quote');
        expect(escapeLabelValue("back\\slash")).to.equal("back\\\\slash");
        expect(escapeLabelValue("new\nline")).to.equal("new\\nline");
    });
});

