describe("tls-options => parseCaCertificates", () => {
    it("returns an empty list for empty input", () => {
        expect(parseCaCertificates(undefined)).to.deep.equal([]);
        expect(parseCaCertificates("")).to.deep.equal([]);
        expect(parseCaCertificates("   \n ")).to.deep.equal([]);
    });

    it("extracts a single certificate", () => {
        const certs = parseCaCertificates(`\n${TEST_CA_PEM}\n`);
        expect(certs).to.have.length(1);
        expect(certs[0]).to.equal(TEST_CA_PEM.trim());
    });

    it("extracts every certificate of a bundle", () => {
        const certs = parseCaCertificates(`${TEST_CA_PEM}\n${SECOND_CA_PEM}`);
        expect(certs).to.deep.equal([TEST_CA_PEM.trim(), SECOND_CA_PEM.trim()]);
    });

    it("accepts Windows line endings", () => {
        const certs = parseCaCertificates(TEST_CA_PEM.replace(/\n/g, "\r\n"));
        expect(certs).to.have.length(1);
    });

    it("rejects text without a PEM certificate block", () => {
        expect(() => parseCaCertificates("not a certificate")).to.throw(/no PEM certificate/i);
    });

    it("rejects a PEM block with broken content", () => {
        const broken = "-----BEGIN CERTIFICATE-----\nAAAA\n-----END CERTIFICATE-----";
        expect(() => parseCaCertificates(broken)).to.throw(/invalid CA certificate/i);
    });
});

describe("tls-options => buildHttpsAgent", () => {
    it("returns undefined when nothing is configured", () => {
        expect(buildHttpsAgent({})).to.equal(undefined);
        expect(buildHttpsAgent({ caCert: "", allowInsecureTls: false })).to.equal(undefined);
    });

    it("keeps the default root certificates when adding a custom CA", () => {
        const agent = buildHttpsAgent({ caCert: TEST_CA_PEM });
        const ca = agent?.options.ca as string[];
        expect(ca).to.include(TEST_CA_PEM.trim());
        expect(ca).to.include.members([...tls.rootCertificates]);
        expect(agent?.options.rejectUnauthorized).to.equal(true);
    });

    it("disables certificate verification only when explicitly allowed", () => {
        const agent = buildHttpsAgent({ allowInsecureTls: true });
        expect(agent?.options.rejectUnauthorized).to.equal(false);
        expect(agent?.options.ca).to.equal(undefined);
    });

    it("throws on an invalid CA certificate", () => {
        expect(() => buildHttpsAgent({ caCert: "garbage" })).to.throw();
    });
});

describe("tls-options => tlsSettingsFromMessage", () => {
    it("returns undefined when the message carries no TLS values", () => {
        expect(tlsSettingsFromMessage({ url: "https://prom:9090" })).to.equal(undefined);
    });

    it("reads the CA certificate and the insecure flag", () => {
        expect(tlsSettingsFromMessage({ caCert: TEST_CA_PEM, allowInsecureTls: true })).to.deep.equal({
            caCert: TEST_CA_PEM,
            allowInsecureTls: true,
        });
    });

    it("accepts the insecure flag as string and ignores non-string CA values", () => {
        expect(tlsSettingsFromMessage({ caCert: 42, allowInsecureTls: "true" })).to.deep.equal({
            caCert: undefined,
            allowInsecureTls: true,
        });
        expect(tlsSettingsFromMessage({ caCert: "", allowInsecureTls: "false" })).to.deep.equal({
            caCert: "",
            allowInsecureTls: false,
        });
    });
});

/**
 * TLS settings for HTTPS connections to Prometheus servers.
 *
 * Supports servers whose certificate is signed by an internal CA (the CA is
 * added on top of Node's default root certificates) and, as a last resort,
 * disabling certificate verification entirely.
 */

import { X509Certificate } from "node:crypto";
import https from "node:https";
import tls from "node:tls";

/** User-facing TLS settings */
export interface TlsSettings {
    /** Optional PEM text with one or more CA certificates */
    caCert?: string;
    /** Skips certificate verification (insecure) */
    allowInsecureTls?: boolean;
}

/**
 * The trust store Node uses by default. Since Node 22.15 this includes
 * NODE_EXTRA_CA_CERTS and, with --use-system-ca, the system store.
 */
function defaultCaCertificates(): readonly string[] {
    return typeof tls.getCACertificates === "function" ? tls.getCACertificates("default") : tls.rootCertificates;
}

const PEM_BLOCK = /-----BEGIN CERTIFICATE-----[\s\S]+?-----END CERTIFICATE-----/g;

/**
 * Extracts and validates all PEM certificate blocks from user input
 *
 * @param raw - PEM text as entered in the Admin UI
 * @returns The normalized certificate blocks, empty when the input is empty
 */
export function parseCaCertificates(raw: string | undefined): string[] {
    const text = (raw ?? "").replace(/\r\n/g, "\n").trim();
    if (!text) {
        return [];
    }
    const blocks = text.match(PEM_BLOCK) ?? [];
    if (blocks.length === 0) {
        throw new Error("CA certificate contains no PEM certificate (expected -----BEGIN CERTIFICATE-----)");
    }
    return blocks.map((block, index) => {
        try {
            new X509Certificate(block);
        } catch (error) {
            const reason = error instanceof Error ? error.message : String(error);
            throw new Error(`Invalid CA certificate #${index + 1}: ${reason}`);
        }
        return block;
    });
}

/**
 * Builds an HTTPS agent for the given TLS settings
 *
 * @param settings - TLS settings from the adapter configuration
 * @returns An agent, or undefined when the Node defaults apply
 */
export function buildHttpsAgent(settings: TlsSettings): https.Agent | undefined {
    const customCas = parseCaCertificates(settings.caCert);
    const insecure = settings.allowInsecureTls === true;
    if (customCas.length === 0 && !insecure) {
        return undefined;
    }
    return new https.Agent({
        // "ca" replaces the default trust store, so the defaults are kept explicitly
        ca: customCas.length > 0 ? [...defaultCaCertificates(), ...customCas] : undefined,
        rejectUnauthorized: !insecure,
    });
}

/**
 * Reads TLS settings sent by the Admin UI (unsaved form values)
 *
 * @param message - Raw sendTo payload
 * @returns The settings, or undefined when the message carries none
 */
export function tlsSettingsFromMessage(message: Record<string, unknown>): TlsSettings | undefined {
    if (!("caCert" in message) && !("allowInsecureTls" in message)) {
        return undefined;
    }
    return {
        caCert: typeof message.caCert === "string" ? message.caCert : undefined,
        allowInsecureTls: message.allowInsecureTls === true || message.allowInsecureTls === "true",
    };
}
